head.script:
/* ================= KHỞI TẠO ================= */
scwin.countdownTimer = null;
scwin.toastTimer = null;

scwin.onpageload = function() {
    dma_productSearch.set("type", "BEST");
    dma_productSearch.set("limit", 8);

    $p.executeSubmission("sbm_getCategories");
    $p.executeSubmission("sbm_getProducts");
    $p.executeSubmission("sbm_getPromo");
};

scwin.onpageunload = function() {
    if (scwin.countdownTimer) {
        clearInterval(scwin.countdownTimer);
    }
};

/* ================= ĐƯỜNG DẪN TRANG =================
   Sửa tại đây khi tạo các trang con trong thư mục E-SalePage */
scwin.PAGE = {
    home: "/E-SalePage/Index.xml",
    productList: "/E-SalePage/ProductList.xml",
    productSale: "/E-SalePage/ProductSale.xml",
    productDetail: "/E-SalePage/ProductDetail.xml",
    login: "/E-SalePage/Login.xml"
};

/* ================= HÀM DÙNG CHUNG ================= */
scwin.goPage = function(xmlPath, param) {
    var url = "/websquare/websquare.html?w2xPath=" + xmlPath;
    if (param) {
        url += "&" + param;
    }
    location.href = url;
};

scwin.formatPrice = function(value) {
    return Number(value || 0).toLocaleString("vi-VN") + "₫";
};

scwin.pad2 = function(n) {
    return (n < 10 ? "0" : "") + n;
};

// Thông báo nhỏ ở góc màn hình
scwin.showToast = function(msg) {
    tbx_toast.setValue(msg);
    grp_toast.addClass("es-toast--show");
    if (scwin.toastTimer) {
        clearTimeout(scwin.toastTimer);
    }
    scwin.toastTimer = setTimeout(function() {
        grp_toast.removeClass("es-toast--show");
    }, 2600);
};

// Cập nhật số lượng trên header chung
scwin.refreshHeaderCart = function() {
    try {
        wfm_header.getWindow().scwin.refreshCart();
    } catch (err) {
        console.warn("Không gọi được header.refreshCart", err);
    }
};

/* ================= RENDER ================= */
scwin.renderCategories = function() {
    gen_category.removeAll();
    var cnt = dlt_category.getRowCount();
    for (var i = 0; i < cnt; i++) {
        var idx = gen_category.insertChild();
        var tile = gen_category.getChild(idx, "grp_cateTile");
        gen_category.getChild(idx, "tbx_cateName").setValue(dlt_category.getCellData(i, "cateName"));
        gen_category.getChild(idx, "tbx_cateCount").setValue(dlt_category.getCellData(i, "itemCount") + " sản phẩm");
        tile.addClass("es-cate--tone" + (dlt_category.getCellData(i, "tone") || ((i % 4) + 1)));
    }
};

scwin.renderProducts = function() {
    gen_product.removeAll();
    var cnt = dlt_product.getRowCount();
    grp_productEmpty.hide();
    if (cnt === 0) {
        grp_productEmpty.show("");
        return;
    }
    for (var i = 0; i < cnt; i++) {
        var idx = gen_product.insertChild();
        var media = gen_product.getChild(idx, "grp_productMedia");
        var img = gen_product.getChild(idx, "img_product");
        var discount = gen_product.getChild(idx, "tbx_discount");
        var oldPrice = gen_product.getChild(idx, "tbx_oldPrice");

        var imageUrl = dlt_product.getCellData(i, "imageUrl");
        var rate = Number(dlt_product.getCellData(i, "discountRate") || 0);

        // Ảnh: nếu chưa có ảnh thì hiển thị khối màu + tên danh mục
        if (imageUrl) {
            img.setSrc(imageUrl);
        } else {
            img.hide();
            media.addClass("es-product__media--tone" + ((i % 4) + 1));
            gen_product.getChild(idx, "tbx_mediaText").setValue(dlt_product.getCellData(i, "cateName"));
        }

        if (rate > 0) {
            discount.setValue("-" + rate + "%");
            oldPrice.setValue(scwin.formatPrice(dlt_product.getCellData(i, "oldPrice")));
        } else {
            discount.hide();
            oldPrice.hide();
        }

        gen_product.getChild(idx, "tbx_productCate").setValue(dlt_product.getCellData(i, "cateName"));
        gen_product.getChild(idx, "anc_productName").setValue(dlt_product.getCellData(i, "productName"));
        gen_product.getChild(idx, "tbx_price").setValue(scwin.formatPrice(dlt_product.getCellData(i, "price")));
    }
};

/* ================= FLASH SALE COUNTDOWN ================= */
scwin.startCountdown = function() {
    tbx_promoTitle.setValue(dma_promo.get("title"));
    tbx_promoDesc.setValue(dma_promo.get("description"));

    var endTime = new Date(dma_promo.get("endTime")).getTime();
    if (isNaN(endTime)) {
        grp_promo.hide();
        return;
    }
    if (scwin.countdownTimer) {
        clearInterval(scwin.countdownTimer);
    }

    var tick = function() {
        var diff = Math.max(0, Math.floor((endTime - Date.now()) / 1000));
        var h = Math.floor(diff / 3600);
        var m = Math.floor((diff % 3600) / 60);
        var s = diff % 60;
        tbx_cdHour.setValue(scwin.pad2(h));
        tbx_cdMin.setValue(scwin.pad2(m));
        tbx_cdSec.setValue(scwin.pad2(s));
        if (diff === 0) {
            clearInterval(scwin.countdownTimer);
            tbx_promoDesc.setValue("Chương trình đã kết thúc. Hẹn bạn ở đợt sale tiếp theo.");
            btn_promoShop.hide();
        }
    };
    tick();
    scwin.countdownTimer = setInterval(tick, 1000);
};

/* ================= DỮ LIỆU MẪU (xóa khi đã có API) ================= */
scwin.loadMockCategories = function() {
    dlt_category.setJSON([
        { cateId: "WOMEN", cateName: "Thời trang nữ", itemCount: 428, tone: "1" },
        { cateId: "MEN", cateName: "Thời trang nam", itemCount: 356, tone: "2" },
        { cateId: "KIDS", cateName: "Trẻ em", itemCount: 190, tone: "3" },
        { cateId: "ACC", cateName: "Phụ kiện", itemCount: 144, tone: "4" }
    ]);
};

scwin.loadMockProducts = function(type) {
    var best = [
        { productId: "P01", productName: "Áo khoác dạ dáng dài", cateName: "Nữ", imageUrl: "", price: 899000, oldPrice: 1290000, discountRate: 30 },
        { productId: "P02", productName: "Sơ mi oxford cổ button", cateName: "Nam", imageUrl: "", price: 389000, oldPrice: 0, discountRate: 0 },
        { productId: "P03", productName: "Quần tây ống suông", cateName: "Nữ", imageUrl: "", price: 459000, oldPrice: 590000, discountRate: 22 },
        { productId: "P04", productName: "Áo len cổ lọ", cateName: "Nam", imageUrl: "", price: 429000, oldPrice: 0, discountRate: 0 },
        { productId: "P05", productName: "Váy midi xếp ly", cateName: "Nữ", imageUrl: "", price: 529000, oldPrice: 690000, discountRate: 23 },
        { productId: "P06", productName: "Bộ nỉ bé trai", cateName: "Trẻ em", imageUrl: "", price: 299000, oldPrice: 0, discountRate: 0 },
        { productId: "P07", productName: "Túi tote canvas", cateName: "Phụ kiện", imageUrl: "", price: 199000, oldPrice: 259000, discountRate: 23 },
        { productId: "P08", productName: "Quần jeans slim fit", cateName: "Nam", imageUrl: "", price: 549000, oldPrice: 0, discountRate: 0 }
    ];
    dlt_product.setJSON(type === "NEW" ? best.slice().reverse() : best);
};

scwin.loadMockPromo = function() {
    var end = new Date(Date.now() + 5 * 3600 * 1000 + 42 * 60 * 1000);
    dma_promo.set("title", "Flash sale cuối tuần: giảm đến 50%");
    dma_promo.set("description", "Áo khoác, len và đồ thu đông. Số lượng có hạn cho mỗi mẫu.");
    dma_promo.set("endTime", end.toISOString());
};

/* ================= SUBMISSION CALLBACK ================= */
scwin.sbm_getCategories_submitdone = function(e) {
    scwin.renderCategories();
};
scwin.sbm_getCategories_submiterror = function(e) {
    scwin.loadMockCategories();
    scwin.renderCategories();
};

scwin.sbm_getProducts_submitdone = function(e) {
    scwin.renderProducts();
};
scwin.sbm_getProducts_submiterror = function(e) {
    scwin.loadMockProducts(dma_productSearch.get("type"));
    scwin.renderProducts();
};

scwin.sbm_getPromo_submitdone = function(e) {
    scwin.startCountdown();
};
scwin.sbm_getPromo_submiterror = function(e) {
    scwin.loadMockPromo();
    scwin.startCountdown();
};

scwin.sbm_addToCart_submitdone = function(e) {
    scwin.showToast("Đã thêm vào giỏ hàng.");
    scwin.refreshHeaderCart();
};

scwin.sbm_addWishlist_submitdone = function(e) {
    scwin.showToast("Đã lưu vào danh sách yêu thích.");
    scwin.refreshHeaderCart();
};

// 401 = chưa đăng nhập -> chuyển sang trang đăng nhập
scwin.sbm_needLogin_submiterror = function(e) {
    if (e && e.responseStatusCode === 401) {
        scwin.goPage(scwin.PAGE.login, "returnUrl=" + encodeURIComponent(location.href));
        return;
    }
    scwin.showToast("Chưa thực hiện được. Vui lòng thử lại.");
};

/* ================= UI EVENT ================= */
// Hero
scwin.btn_heroShop_onclick = function(e) {
    scwin.goPage(scwin.PAGE.productList, "collection=FW2026");
};
scwin.btn_heroSale_onclick = function(e) {
    scwin.goPage(scwin.PAGE.productSale);
};

// Danh mục
scwin.grp_cateTile_onclick = function(e) {
    var idx = this.getGeneratedIndex();
    scwin.goPage(scwin.PAGE.productList, "cateId=" + dlt_category.getCellData(idx, "cateId"));
};

// Tab sản phẩm
scwin.changeTab = function(type) {
    if (dma_productSearch.get("type") === type) {
        return;
    }
    btn_tabBest.removeClass("es-tab--active");
    btn_tabNew.removeClass("es-tab--active");
    (type === "BEST" ? btn_tabBest : btn_tabNew).addClass("es-tab--active");
    dma_productSearch.set("type", type);
    $p.executeSubmission("sbm_getProducts");
};
scwin.btn_tabBest_onclick = function(e) {
    scwin.changeTab("BEST");
};
scwin.btn_tabNew_onclick = function(e) {
    scwin.changeTab("NEW");
};

// Sản phẩm
scwin.openProduct = function(idx) {
    scwin.goPage(scwin.PAGE.productDetail, "productId=" + dlt_product.getCellData(idx, "productId"));
};
scwin.grp_productMedia_onclick = function(e) {
    scwin.openProduct(this.getGeneratedIndex());
};
scwin.anc_productName_onclick = function(e) {
    scwin.openProduct(this.getGeneratedIndex());
};

scwin.btn_addCart_onclick = function(e) {
    var idx = this.getGeneratedIndex();
    dma_cartItem.set("productId", dlt_product.getCellData(idx, "productId"));
    dma_cartItem.set("quantity", 1);
    $p.executeSubmission("sbm_addToCart");
};

scwin.btn_wish_onclick = function(e) {
    if (e && e.stopPropagation) {
        e.stopPropagation(); // không mở trang chi tiết khi bấm tim
    }
    var idx = this.getGeneratedIndex();
    this.addClass("es-product__wish--on");
    dma_cartItem.set("productId", dlt_product.getCellData(idx, "productId"));
    dma_cartItem.set("quantity", 1);
    $p.executeSubmission("sbm_addWishlist");
};

scwin.btn_viewAll_onclick = function(e) {
    scwin.goPage(scwin.PAGE.productList, "sort=" + dma_productSearch.get("type"));
};

// Flash sale
scwin.btn_promoShop_onclick = function(e) {
    scwin.goPage(scwin.PAGE.productSale);
};
